      "content": "{\n  \"name\": \"@anionex/dsh-computer-use\",\n  \"version\": \"0.3.4\",\n  \"description\": \"Accessibility-first macOS Computer Use capability for DeepSeek Harness with stale-observation protection, app leases, confirmations, screenshots, and Web diagnostics\",\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"computer-use\",\n    \"macos\",\n    \"accessibility\",\n    \"desktop-automation\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Anionex/dsh-computer-use.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/Anionex/dsh-computer-use/issues\"\n  },\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.20.0\",\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./service\": {\n      \"types\": \"./lib/types/service.d.ts\",\n      \"default\": \"./lib/service.js\"\n    },\n    \"./provider-macos\": {\n      \"types\": \"./lib/types/providers/macos.d.ts\",\n      \"default\": \"./lib/providers/macos.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"assets\",\n    \"native/macos/Sources\",\n    \"native/macos/bin\",\n    \"native/macos/manifest.json\",\n    \"scripts\",\n    \"docs\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.zh.md\",\n    \"LICENSE\",\n    \"CHANGELOG.md\"\n  ],\n  \"scripts\": {\n    \"native:build\": \"node scripts/build-native.mjs\",\n    \"check:native\": \"node scripts/check-native.mjs\",\n    \"build\": \"pnpm run native:build && tsc -p tsconfig.json && tsc -p tsconfig.client.json && node scripts/build-client.mjs\",\n    \"prepack\": \"pnpm run build\",\n    \"test\": \"pnpm run build && vitest run tests\",\n    \"test:model\": \"node scripts/model-e2e.mjs\",\n    \"test:watch\": \"vitest tests\",\n    \"validate\": \"node scripts/validate.mjs --lane all\",\n    \"validate:local\": \"node scripts/validate.mjs --lane local\",\n    \"validate:profile\": \"node scripts/validate.mjs --lane profile\",\n    \"validate:model\": \"node scripts/model-e2e.mjs\",\n    \"validate:release\": \"pnpm run validate && pnpm run validate:model\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-renderer\",\n        \"@deepseek-ai/dsh-client-ui-settings-general\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-connection\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dsh\": \">=0.1.0-rc.8 <0.2.0 || >=0.1.1-rc.1 <0.2.0 || >=0.1.2-alpha.3 <0.2.0 || >=0.1.5-rc.1 <0.2.0 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n      \"dshReleases\": {\n        \"0.1.0-rc.8\": \"compatible\",\n        \"0.1.1-rc.1\": \"compatible\",\n        \"0.1.1-rc.2\": \"compatible\",\n        \"0.1.2-alpha.3\": \"compatible\",\n        \"0.1.2-alpha.4\": \"compatible\",\n        \"0.1.2-alpha.5\": \"compatible\",\n        \"0.1.5-alpha.1\": \"compatible\",\n        \"0.1.5-alpha.2\": \"compatible\",\n        \"0.1.5-rc.1\": \"compatible\",\n        \"0.1.7-rc.2\": \"compatible\",\n        \"0.2.0-rc.2\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\"\n      },\n      \"profiles\": [\n        \"web\"\n      ]\n    }\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-agent\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-api-remotes\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-brand\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-skill\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-storage-domain\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-subprocess\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"^0.1.0-rc.6 || 0.1.7-rc.2 || 0.2.0-rc.2 || 0.2.1-rc.2\",\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"react\": \"^18.2.0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"@deepseek-ai/dsh-util-values\": \"^0.1.0-rc.6 || 0.2.0-rc.2 || 0.2.1-rc.2\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-host-webserver\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.20.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.0\",\n    \"typescript\": \"^6.0.3\",\n    \"vitest\": \"^4.1.10\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-brand\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-skill\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-storage-domain\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@deepseek-ai/dsh-util-values\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-storage\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/cosmokit\": \"1.8.5\",\n    \"@deepseek-ai/dsh-credentials\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-util-crypto\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-timeout\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-http-proxy\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"1.0.5\",\n    \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-util-code-language\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-deque\": \"0.2.1-rc.2\"\n  },\n  \"dependencies\": {\n    \"zod\": \"4.4.3\"\n  },\n  \"license\": \"MIT\"\n}