    {
      "path": "src/leases.ts",
      "content": "/** Session-sidecar read leases, durable denials, and per-turn control leases. */\n\nimport { z } from 'zod'\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { ToolRunContext } from '@deepseek-ai/dsh-tools'\ntype CallId = ToolRunContext['callId']\nimport type { SessionEvent, SessionHeader, SessionId } from '@deepseek-ai/dsh-session'\nimport { defineDomain, domainTable } from '@deepseek-ai/dsh-storage-domain'\nimport type { KvTable } from '@deepseek-ai/dsh-storage-domain'\nimport type { Context, Fiber } from '@deepseek-ai/cordis'\nimport { approvalPolicy } from './approval-policy.ts'\nimport type { ResolvedComputerUseConfig } from './config.ts'\nimport { ComputerUseError } from './errors.ts'\nimport type { ComputerAppIdentity } from './types.ts'\n\nconst nonNegativeSafeInteger = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER)\nconst leaseScopeSchema = z.union([z.literal('read'), z.literal('control')])\n\nconst sessionIdentitySchema = z.object({\n  createdAt: nonNegativeSafeInteger,\n  cwd: z.string().optional(),\n})\n\n/** Session fields that fence one sidecar row to one exact Session lifecycle. */\nexport type ComputerUseSessionIdentity = z.infer<typeof sessionIdentitySchema>\n\nconst deniedLeaseSchema = z.object({\n  bundleId: z.string().min(1),\n  scope: leaseScopeSchema,\n})\n\n/** One application/scope rejection that remains final for the Session lifecycle. */\nexport type ComputerUseDeniedLease = z.infer<typeof deniedLeaseSchema>\n\n/** Runtime validation for the whole-Session Computer Use sidecar row. */\nexport const computerUseSessionStateSchema = z.object({\n  session: sessionIdentitySchema,\n  readGrants: z.array(z.string().min(1)),\n  denied: z.array(deniedLeaseSchema),\n}).superRefine((row, ctx) => {\n  const readGrants = new Set<string>()\n  row.readGrants.forEach((bundleId, index) => {\n    if (readGrants.has(bundleId)) {\n      ctx.addIssue({\n        code: 'custom',\n        path: ['readGrants', index],\n        message: `duplicate Computer Use read grant '${bundleId}'`,\n      })\n    }\n    readGrants.add(bundleId)\n  })\n\n  const denials = new Set<string>()\n  row.denied.forEach((denial, index) => {\n    const key = `${denial.scope}\\0${denial.bundleId}`\n    if (denials.has(key)) {\n      ctx.addIssue({\n        code: 'custom',\n        path: ['denied', index],\n        message: `duplicate Computer Use ${denial.scope} denial '${denial.bundleId}'`,\n      })\n    }\n    denials.add(key)\n  })\n})\n\n/** Plugin-owned durable authorization state for one Session lifecycle. */\nexport type ComputerUseSessionState = z.infer<typeof computerUseSessionStateSchema>\n\n/** One lifecycle-bound Computer Use sidecar record per Session id. */\nexport const computerUseStateDomainSpec = defineDomain({\n  name: 'computer_use_state',\n  version: 0,\n  tables: {\n    sessions: domainTable<SessionId, ComputerUseSessionState>(computerUseSessionStateSchema),\n  },\n})\n\ninterface StorageBinding {\n  table: KvTable<SessionId, ComputerUseSessionState>\n}\n\nfunction currentTurn(events: readonly SessionEvent[]): number | undefined {\n  for (let index = events.length - 1; index >= 0; index -= 1) {\n    const event = events[index]\n    if (event?.type === 'turn/end') return undefined\n    if (event?.type === 'turn/start') return event.data.turn\n  }\n  return undefined\n}\n\nfunction identityOf(header: SessionHeader): ComputerUseSessionIdentity {\n  return Object.freeze({\n    createdAt: header.createdAt,\n    ...(header.cwd === undefined ? {} : { cwd: header.cwd }),\n  })\n}\n\nfunction sameIdentity(row: ComputerUseSessionState, header: SessionHeader): boolean {\n  return row.session.createdAt === header.createdAt && row.session.cwd === header.cwd\n}\n\nfunction stateSnapshot(\n  header: SessionHeader,\n  readGrants: Iterable<string>,\n  denied: Iterable<ComputerUseDeniedLease>,\n): ComputerUseSessionState {\n  const readGrantSnapshot = Object.freeze([...readGrants]) as unknown as string[]\n  const deniedSnapshot = Object.freeze([...denied].map(item => Object.freeze({ ...item }))) as unknown as ComputerUseDeniedLease[]\n  return Object.freeze({\n    session: identityOf(header),\n    readGrants: readGrantSnapshot,\n    denied: deniedSnapshot,\n  })\n}\n\nfunction configuredAccess(config: ResolvedComputerUseConfig, bundleId: string, scope: 'read' | 'control'): boolean {\n  if (config.allowAllApps) return true\n  return config.grants.find(grant => grant.bundleId === bundleId)?.[scope] === true\n}\n\nfunction boundedFailure(error: unknown): string {\n  return (error instanceof Error ? error.message : String(error)).slice(0, 500)\n}\n\n/** Source of the technical application lease used by an operation. */\nexport type ComputerLeaseSource = 'configured' | 'approved'\n\n/** Applies configured app policy and routes missing leases through DSH approval. */\nexport class ComputerLeaseManager {\n  private storage: StorageBinding | undefined\n  private readonly storageFiber: Fiber & PromiseLike<Fiber>\n  private readonly decisionTails = new Map<SessionId, Promise<void>>()\n  private readonly mutationTails = new Map<SessionId, Promise<void>>()\n  private readonly controlGrants = new WeakMap<Agent, Map<string, number>>()\n\n  constructor(\n    private readonly ctx: Context,\n    private readonly config: () => ResolvedComputerUseConfig,\n  ) {\n    this.storageFiber = ctx.inject(['storageDomain'], async (storageCtx: Context) => {\n      const domain = await storageCtx.storageDomain.open(computerUseStateDomainSpec)\n      const binding: StorageBinding = { table: domain.table('sessions') }\n      this.storage = binding\n      return async () => {\n        if (this.storage === binding) this.storage = undefined\n        await Promise.all(this.mutationTails.values())\n        await domain.close()\n      }\n    })\n    ctx.effect(() => () => this.storageFiber.dispose(), 'dsh-computer-use: optional lease sidecar')\n  }\n\n  /** Wait for an already-composed storage-domain service to finish opening. */\n  async initialize(): Promise<void> {\n    await this.prepareStorage()\n  }\n\n  /** Ensure one Agent may read or control one exact running application. */\n  async ensure(\n    agent: Agent,\n    app: ComputerAppIdentity,\n    scope: 'read' | 'control',\n    toolName: string,\n    callId: CallId | undefined,\n    signal: AbortSignal,\n  ): Promise<ComputerLeaseSource> {\n    if (configuredAccess(this.config(), app.bundleId, scope)) return 'configured'\n    return await this.enqueueDecision(agent.session.id, async () => {\n      if (configuredAccess(this.config(), app.bundleId, scope)) return 'configured'\n      return await this.ensureInteractive(agent, app, scope, toolName, callId, signal)\n    })\n  }\n\n  /** Forget process-local control grants when their Agent is disposed. */\n  releaseAgent(agent: Agent): void {\n    this.controlGrants.delete(agent)\n  }\n\n  private async ensureInteractive(\n    agent: Agent,\n    app: ComputerAppIdentity,\n    scope: 'read' | 'control',\n    toolName: string,\n    callId: CallId | undefined,\n    signal: AbortSignal,\n  ): Promise<ComputerLeaseSource> {\n    await this.prepareStorage()\n    const sessionEvents = typeof (agent.session as any).snapshotEvents === 'function'\n      ? (agent.session as any).snapshotEvents()\n      : (agent.session as unknown as { events?: readonly SessionEvent[] }).events ?? []\n    const turn = currentTurn(sessionEvents)\n    if (turn === undefined) {\n      throw new ComputerUseError('COMPUTER_PERMISSION_REQUIRED', `${scope} access for ${app.name} must be requested inside an open Agent turn`)\n    }\n\n    if (scope === 'control' && this.controlGrants.get(agent)?.get(app.bundleId) === turn) {\n      return 'approved'\n    }\n\n    const stored = this.currentState(agent)\n    if (scope === 'read' && stored?.readGrants.includes(app.bundleId) === true) {\n      return 'approved'\n    }\n    if (stored?.denied.some(denial => denial.bundleId === app.bundleId && denial.scope === scope) === true) {\n      throw new ComputerUseError(\n        'COMPUTER_PERMISSION_REQUIRED',\n        `${scope} access for ${app.name} was rejected earlier in this Session; do not retry without new user instructions`,\n      )\n    }\n\n    if (approvalPolicy(this.ctx, agent) === 'never') {\n      throw new ComputerUseError(\n        'COMPUTER_PERMISSION_REQUIRED',\n        `${scope} access for ${app.name} is blocked because approval prompts are disabled in this Session (approval/policy: never, e.g. the danger-full-access preset); add \"${app.bundleId}\" to the computer-use grants in Settings, or switch the permission preset to one with approval ask`,\n      )\n    }\n\n    if (scope === 'read' && this.storage === undefined) {\n      throw this.storageRequired(app, scope, 'a Session-wide interactive read grant')\n    }\n\n    const outcome = await this.ctx.approval.request({\n      agent,\n      toolName,\n      ...(callId === undefined ? {} : { callId }),\n      reason: scope === 'read'\n        ? `Allow this Agent to inspect the Accessibility state and requested screenshot of ${app.name} (${app.bundleId}) for this Session.`\n        : `Allow this Agent to send UI input to ${app.name} (${app.bundleId}) for the current turn.`,\n      signal,\n    })\n    if (outcome === 'cancelled') {\n      throw new ComputerUseError('COMPUTER_CANCELLED', `${scope} access request for ${app.name} was cancelled`)\n    }\n    if (outcome === 'rejected') {\n      if (this.storage === undefined) {\n        throw this.storageRequired(app, scope, 'the rejected interactive decision')\n      }\n      await this.persist(agent, app, { kind: 'denied', scope })\n      throw new ComputerUseError('COMPUTER_PERMISSION_REQUIRED', `${scope} access for ${app.name} was not granted (rejected); do not retry in this Session without new user instructions`)\n    }\n    if (outcome !== 'allowed-once') {\n      throw new ComputerUseError('COMPUTER_PERMISSION_REQUIRED', `${scope} access for ${app.name} was not granted (${outcome})`)\n    }\n\n    if (scope === 'control') {\n      let grants = this.controlGrants.get(agent)\n      if (grants === undefined) {\n        grants = new Map()\n        this.controlGrants.set(agent, grants)\n      }\n      grants.set(app.bundleId, turn)\n      return 'approved'\n    }\n\n    await this.persist(agent, app, { kind: 'read-granted' })\n    return 'approved'\n  }\n\n  private currentState(agent: Agent): ComputerUseSessionState | undefined {\n    const row = this.storage?.table.get(agent.session.id)\n    return row !== undefined && sameIdentity(row, agent.session.header) ? row : undefined\n  }\n\n  private async prepareStorage(): Promise<StorageBinding | undefined> {\n    if (this.storage !== undefined) return this.storage\n    if (this.ctx.get('storageDomain') === undefined) return undefined\n    await this.storageFiber\n    return this.storage\n  }\n\n  private async persist(\n    agent: Agent,\n    app: ComputerAppIdentity,\n    decision: { kind: 'read-granted' } | { kind: 'denied'; scope: 'read' | 'control' },\n  ): Promise<void> {\n    const purpose = decision.kind === 'read-granted'\n      ? 'the Session-wide read grant'\n      : `the Session-wide ${decision.scope} denial`\n    try {\n      const participated = await this.ctx.sessions.flush(agent.session)\n      if (!participated) {\n        throw new Error('no Session persistence listener participated in ctx.sessions.flush')\n      }\n      await this.enqueueMutation(agent.session.id, async () => {\n        const binding = this.storage\n        if (binding === undefined) throw this.storageRequired(app, decision.kind === 'read-granted' ? 'read' : decision.scope, purpose)\n        const current = binding.table.get(agent.session.id)\n        const row = current !== undefined && sameIdentity(current, agent.session.header)\n          ? current\n          : stateSnapshot(agent.session.header, [], [])\n        const readGrants = new Set(row.readGrants)\n        const denied = [...row.denied]\n        if (decision.kind === 'read-granted') {\n          readGrants.add(app.bundleId)\n        } else if (!denied.some(item => item.bundleId === app.bundleId && item.scope === decision.scope)) {\n          denied.push({ bundleId: app.bundleId, scope: decision.scope })\n        }\n        await binding.table.put(agent.session.id, stateSnapshot(agent.session.header, readGrants, denied))\n      })\n    } catch (error) {\n      if (error instanceof ComputerUseError) throw error\n      throw new ComputerUseError(\n        'COMPUTER_PERMISSION_REQUIRED',\n        `${purpose} for ${app.name} could not be persisted after the approval audit: ${boundedFailure(error)}; configure working Session persistence and @deepseek-ai/dsh-storage-domain before retrying`,\n        { cause: error },\n      )\n    }\n  }\n\n  private storageRequired(\n    app: ComputerAppIdentity,\n    scope: 'read' | 'control',\n    purpose: string,\n  ): ComputerUseError {\n    return new ComputerUseError(\n      'COMPUTER_PERMISSION_REQUIRED',\n      `${scope} access for ${app.name} requires ctx.storageDomain to persist ${purpose}; compose @deepseek-ai/dsh-storage-domain or add an exact static grant for \"${app.bundleId}\" before retrying`,\n    )\n  }\n\n  private enqueueDecision<T>(sessionId: SessionId, operation: () => Promise<T>): Promise<T> {\n    const previous = this.decisionTails.get(sessionId) ?? Promise.resolve()\n    const result = previous.then(operation)\n    const tail = result.then(() => undefined, () => undefined)\n    this.decisionTails.set(sessionId, tail)\n    return result.finally(() => {\n      if (this.decisionTails.get(sessionId) === tail) this.decisionTails.delete(sessionId)\n    })\n  }\n\n  private enqueueMutation<T>(sessionId: SessionId, operation: () => Promise<T>): Promise<T> {\n    const previous = this.mutationTails.get(sessionId) ?? Promise.resolve()\n    const result = previous.then(operation)\n    const tail = result.then(() => undefined, () => undefined)\n    this.mutationTails.set(sessionId, tail)\n    return result.finally(() => {\n      if (this.mutationTails.get(sessionId) === tail) this.mutationTails.delete(sessionId)\n    })\n  }\n}\n"
    },
    {
      "path": "src/exposure.ts",
      "content": "/** Agent-scoped progressive exposure for Computer Use execution Tools. */\n\nimport type { Agent } from '@deepseek-ai/dsh-agent'\nimport type { ContentBlock } from '@deepseek-ai/dsh-llm'\nimport type { Session } from '@deepseek-ai/dsh-session'\nimport { defineTool, type ToolDefinition } from '@deepseek-ai/dsh-tools'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { COMPUTER_USE_SKILL_CONTENT, COMPUTER_USE_SKILL_NAME, COMPUTER_USE_SKILL_NAMES } from './skill.ts'\n\n/** One global bootstrap retained until the current Agent loads the Skill. */\nexport const COMPUTER_USE_ACTIVATE = 'computer_use_activate'\n\nconst VISION_TOOL_NAMES = [\n  'vision_glance',\n  'vision_ground',\n  'vision_detect',\n  'vision_crop',\n  'vision_long_screenshot_ocr',\n  'vision_toolkit_activate',\n] as const\n\nconst COMMAND_PREFIX = /^(?:(?:[A-Za-z_][A-Za-z0-9_]*=\\S+)\\s+)*(?:(?:\\S*\\/)?(?:sudo|env|nohup|time|command|exec)\\s+(?:(?:-\\S+|[A-Za-z_][A-Za-z0-9_]*=\\S+)\\s+)*)?/iu\nconst OCR_COMMAND_PROBE = /^(?:which|type|command\\s+-v)\\b[^\\n;&|]*\\b(?:tesseract|screencapture)\\b/iu\nconst OCR_EXECUTABLE = /^(?:\\S*\\/)?(?:tesseract|screencapture)(?:\\s|$)/iu\nconst OCR_STACK_SETUP = /^(?:(?:\\S*\\/)?(?:brew|port|apt(?:-get)?|dnf|yum|pacman)\\b[^\\n]*(?:install|add)\\b[^\\n]*\\btesseract(?:-ocr)?\\b|(?:\\S*\\/)?(?:pip(?:3(?:\\.\\d+)*)?|uv\\s+pip|poetry\\s+add|pdm\\s+add)\\b[^\\n]*(?:install|add)?[^\\n]*\\b(?:pytesseract|easyocr|ocrmypdf)\\b)/iu\nconst SCRIPTED_OCR_EXECUTABLE = /^(?:\\S*\\/)?(?:python(?:3(?:\\.\\d+)*)?|swift)(?:\\s|$)/iu\nconst SCRIPTED_OCR_MARKER = /(?:\\bpytesseract\\b|\\beasyocr\\b|\\bocrmypdf\\b|VNRecognizeTextRequest|\\bimport\\s+Vision\\b)/iu\nconst SHELL_META = /(?:&&|\\|\\||[;|\\n])/u\n\ninterface AgentExposure {\n  active: boolean\n  hideActivation?: () => void\n  toolDisposers: Array<() => void>\n  toolNames: string[]\n}\n\n/** Activation result returned to the model. */\nexport interface ComputerUseActivationResult {\n  activated: boolean\n  tools: string[]\n}\n\nfunction renderJson(_args: unknown, value: unknown): ContentBlock[] {\n  return [{ type: 'text', text: JSON.stringify(value, null, 2) }]\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return value !== null && typeof value === 'object' && !Array.isArray(value)\n}\n\nfunction adHocOcrCommand(value: unknown): boolean {\n  if (!isRecord(value) || typeof value.command !== 'string') return false\n  const commands = value.command.split(SHELL_META)\n    .map(command => command.trimStart().replace(COMMAND_PREFIX, ''))\n  if (commands.some(command => OCR_COMMAND_PROBE.test(command)\n    || OCR_EXECUTABLE.test(command)\n    || OCR_STACK_SETUP.test(command))) return true\n  return SCRIPTED_OCR_MARKER.test(value.command)\n    && commands.some(command => SCRIPTED_OCR_EXECUTABLE.test(command))\n}\n\nfunction isSkillArguments(value: unknown): boolean {\n  return isRecord(value) && COMPUTER_USE_SKILL_NAMES.has(value.name as string)\n}\n\nfunction nativeSkillCall(raw: string): boolean {\n  try { return isSkillArguments(JSON.parse(raw)) } catch { return false }\n}\n\nfunction containsSkillContent(blocks: readonly unknown[]): boolean {\n  return blocks.some(block => isRecord(block)\n    && block.type === 'text'\n    && typeof block.text === 'string'\n    && block.text.includes(COMPUTER_USE_SKILL_CONTENT))\n}\n\nfunction isSkillResult(value: unknown): boolean {\n  return isRecord(value)\n    && COMPUTER_USE_SKILL_NAMES.has(value.name as string)\n    && value.content === COMPUTER_USE_SKILL_CONTENT\n}\n\n/**\n * Session event types carrying one PTC (`run_code`) sub-dispatch.\n *\n * DSH 0.1.5 renamed the append site from `tool/code-dispatch` to\n * `tool/ptc-dispatch` (`dsh-tools`) with an identical payload, and its session\n * format migration renames replayed legacy events to the new name, so a log\n * can legitimately carry either. Both are accepted: a pre-0.1.5 host only ever\n * appends the old name, a 0.1.5 host only the new one.\n */\nconst PTC_DISPATCH_EVENT_TYPES: ReadonlySet<string> = new Set(['tool/ptc-dispatch', 'tool/code-dispatch'])\n\n/** Whether durable Session history proves that the bundled Skill was loaded. */\nexport function hasLoadedComputerUseSkill(session: Session): boolean {\n  const nativeCalls = new Set<string>()\n  const events = typeof (session as any).snapshotEvents === 'function'\n    ? (session as any).snapshotEvents()\n    : (session as unknown as { events?: readonly import('@deepseek-ai/dsh-session').SessionEvent[] }).events ?? []\n  for (const event of events) {\n    if (event.type === 'user/message') {\n      const source = event.data.source\n      if (source.kind === 'skill-invocation'\n        && COMPUTER_USE_SKILL_NAMES.has(source.name)\n        && containsSkillContent(event.data.content)) return true\n      continue\n    }\n    if (event.type === 'tool/call') {\n      if (event.data.name === 'skill' && nativeSkillCall(event.data.arguments)) nativeCalls.add(String(event.data.callId))\n      continue\n    }\n    if (event.type === 'tool/result') {\n      const [block] = event.data.message.content\n      if (block?.type === 'tool-result'\n        && block.isError !== true\n        && nativeCalls.has(String(block.toolCallId))\n        && containsSkillContent(block.content)) return true\n      continue\n    }\n    if (PTC_DISPATCH_EVENT_TYPES.has(event.type)\n      && event.data.name === 'skill'\n      && event.data.isError === false\n      && isSkillArguments(event.data.arguments)\n      && containsSkillContent(event.data.content)) return true\n  }\n  return false\n}\n\n/** Owns one progressive Tool-exposure generation. */\nexport class ComputerUseExposure {\n  readonly activationTool: ToolDefinition\n  private readonly states = new Map<Agent, AgentExposure>()\n  private installed = false\n\n  constructor(\n    private readonly ctx: Context,\n    private readonly createTools: () => ToolDefinition[],\n  ) {\n    this.activationTool = defineTool({\n      name: COMPUTER_USE_ACTIVATE,\n      description: `Activate the macOS Computer Use execution tools for this Agent after loading the ${COMPUTER_USE_SKILL_NAME} Skill. The Skill tool normally activates them automatically; call this only after a direct Skill invocation when the tools are still absent. This bootstrap disappears after success.`,\n      parameters: {},\n      output: {\n        schema: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            activated: { type: 'boolean', required: true },\n            tools: { type: 'array', items: { type: 'string' }, required: true },\n          },\n        },\n        render: renderJson,\n      },\n      execute: (_args, exec): Promise<ComputerUseActivationResult> => {\n        if (exec.agent === undefined) throw new Error(`${COMPUTER_USE_ACTIVATE}: an Agent Session is required`)\n        if (!hasLoadedComputerUseSkill(exec.agent.session)) {\n          throw new Error(`${COMPUTER_USE_ACTIVATE}: load the ${COMPUTER_USE_SKILL_NAME} Skill first`)\n        }\n        return Promise.resolve(this.activate(exec.agent))\n      },\n      presentCall: () => ({ card: 'generic', title: 'Activate Computer Use', kind: 'execute' }),\n    })\n  }\n\n  /** Install lifecycle listeners and adopt existing Agents. */\n  install(): () => void {\n    if (this.installed) throw new Error('dsh-computer-use: progressive exposure is already installed')\n    this.installed = true\n    const effects = [\n      this.ctx.on('agent/created', ({ agent }) => { this.attach(agent) }),\n      this.ctx.on('agent/disposed', ({ agent }) => { this.detach(agent) }),\n      this.ctx.tools.guard((exec) => {\n        if (exec.name !== 'bash'\n          || exec.agent === undefined\n          || !hasLoadedComputerUseSkill(exec.agent.session)\n          || !adHocOcrCommand(exec.arguments)\n          || !VISION_TOOL_NAMES.some(name => this.ctx.tools.get(name, exec.agent) !== undefined)) return undefined\n        return 'Computer Use screenshot analysis must use the installed Vision Toolkit instead of a shell-built OCR stack. If vision_glance is absent, call the skill tool with {\"name\":\"vision-tools\"}; then pass the existing screenshot Artifact path to vision_glance, vision_ground, vision_detect, vision_crop, or vision_long_screenshot_ocr.'\n      }),\n      this.ctx.on('tools/result', (exec, result) => {\n        if (result.isError === false\n          && exec.name === 'skill'\n          && exec.agent !== undefined\n          && isSkillArguments(exec.arguments)\n          && isSkillResult(result.value)) this.activate(exec.agent)\n        return undefined\n      }),\n    ]\n    try {\n      for (const agent of this.ctx.agents.list()) this.attach(agent)\n    } catch (error) {\n      for (const dispose of effects.reverse()) dispose()\n      this.disposeStates()\n      this.installed = false\n      throw error\n    }\n    return () => {\n      if (!this.installed) return\n      this.installed = false\n      for (const dispose of effects.reverse()) dispose()\n      this.disposeStates()\n    }\n  }\n\n  private attach(agent: Agent): void {\n    if (this.states.has(agent)) return\n    this.states.set(agent, { active: false, toolDisposers: [], toolNames: [] })\n    if (hasLoadedComputerUseSkill(agent.session)) this.activate(agent)\n  }\n\n  private activate(agent: Agent): ComputerUseActivationResult {\n    this.attach(agent)\n    const state = this.states.get(agent)\n    if (state === undefined) throw new Error(`dsh-computer-use: Agent ${String(agent.id)} has no exposure state`)\n    if (state.active) return { activated: false, tools: [...state.toolNames] }\n    const definitions = this.createTools()\n    const toolDisposers: Array<() => void> = []\n    let hideActivation: (() => void) | undefined\n    try {\n      for (const definition of definitions) toolDisposers.push(agent.ctx.tools.register(definition))\n      hideActivation = agent.ctx.tools.restrict({ deny: [COMPUTER_USE_ACTIVATE] })\n    } catch (error) {\n      hideActivation?.()\n      for (const dispose of toolDisposers.reverse()) dispose()\n      throw error\n    }\n    state.active = true\n    state.hideActivation = hideActivation\n    state.toolDisposers = toolDisposers\n    state.toolNames = definitions.map(definition => definition.name)\n    return { activated: true, tools: [...state.toolNames] }\n  }\n\n  private detach(agent: Agent): void {\n    const state = this.states.get(agent)\n    if (state === undefined) return\n    this.states.delete(agent)\n    this.disposeState(state)\n  }\n\n  private disposeStates(): void {\n    for (const state of this.states.values()) this.disposeState(state)\n    this.states.clear()\n  }\n\n  private disposeState(state: AgentExposure): void {\n    state.hideActivation?.()\n    for (const dispose of state.toolDisposers.reverse()) dispose()\n  }\n}\n"
    },
